import { Bell, Mail, MessageSquare } from "lucide-react";

import { cn } from "@/lib/utils";

import { Checkbox } from "@/components/ui/checkbox";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface NotificationSettingItem {
  id: string;
  title: string;
  description: string;
  email: boolean;
  sms: boolean;
}

interface SettingsNotifications4Props {
  heading?: string;
  subHeading?: string;
  className?: string;
  notifications?: NotificationSettingItem[];
}

const SettingsNotifications4 = ({
  heading = "Notifications",
  subHeading = "Manage your email and SMS notification preferences",
  notifications = [
    {
      id: "mentions",
      title: "Direct Mentions",
      description: "Get alerted when someone tags you using @.",
      email: true,
      sms: false,
    },
    {
      id: "comments",
      title: "Comments",
      description: "Receive updates when someone comments on your posts.",
      email: true,
      sms: false,
    },
    {
      id: "messages",
      title: "Direct Messages",
      description: "New private messages from other users.",
      email: true,
      sms: true,
    },
    {
      id: "assignments",
      title: "Task Assignments",
      description: "When a task is assigned to you.",
      email: true,
      sms: false,
    },
    {
      id: "deadlines",
      title: "Deadline Reminders",
      description: "Reminders for upcoming due dates.",
      email: true,
      sms: true,
    },
    {
      id: "security",
      title: "Security Alerts",
      description: "Important security notifications for your account.",
      email: true,
      sms: true,
    },
    {
      id: "billing",
      title: "Billing Updates",
      description: "Notifications about payments and invoices.",
      email: true,
      sms: false,
    },
  ],
  className,
}: SettingsNotifications4Props) => {
  return (
    <section className="py-32">
      <div
        className={cn(
          "container max-w-4xl space-y-8 tracking-tight",
          className,
        )}
      >
        <div className="space-y-2">
          <h3 className="text-2xl font-semibold">{heading}</h3>
          <p className="font-medium text-muted-foreground">{subHeading}</p>
        </div>

        <Table>
          <TableHeader>
            <TableRow className="[&_div]:flex [&_div]:items-center [&_div]:justify-center [&_div]:gap-1.5 [&_div]:font-semibold [&_div]:text-muted-foreground/80 [&_div_svg]:size-4">
              <TableHead>
                <div className="!justify-start">
                  <Bell /> Notify me about
                </div>
              </TableHead>
              <TableHead>
                <div>
                  <Mail /> Email
                </div>
              </TableHead>
              <TableHead>
                <div>
                  <MessageSquare /> SMS
                </div>
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {notifications.map((notification) => (
              <TableRow key={notification.id}>
                <TableCell>
                  <p className="font-semibold">{notification.title}</p>
                  <p className="text-xs font-medium text-muted-foreground/70">
                    {notification.description}
                  </p>
                </TableCell>
                <TableCell className="text-center">
                  <Checkbox defaultChecked={notification.email} />
                </TableCell>
                <TableCell className="text-center">
                  <Checkbox defaultChecked={notification.sms} />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </section>
  );
};

export { SettingsNotifications4 };

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client"

import * as React from "react"
import * as CheckboxPrimitive from "@radix-ui/react-checkbox"
import { CheckIcon } from "lucide-react"

import { cn } from "@/lib/utils"

function Checkbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer border-input dark:bg-input/30 data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground dark:data-[state=checked]:bg-primary data-[state=checked]:border-primary focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive size-4 shrink-0 rounded-[4px] border shadow-xs transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none"
      >
        <CheckIcon className="size-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function Table({ className, ...props }: React.ComponentProps<"table">) {
  return (
    <div
      data-slot="table-container"
      className="relative w-full overflow-x-auto"
    >
      <table
        data-slot="table"
        className={cn("w-full caption-bottom text-sm", className)}
        {...props}
      />
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("[&_tr]:border-b", className)}
      {...props}
    />
  )
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  )
}

function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "bg-muted/50 border-t font-medium [&>tr]:last:border-b-0",
        className
      )}
      {...props}
    />
  )
}

function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "hover:bg-muted/50 data-[state=selected]:bg-muted border-b transition-colors",
        className
      )}
      {...props}
    />
  )
}

function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "text-foreground h-10 px-2 text-left align-middle font-medium whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]",
        className
      )}
      {...props}
    />
  )
}

function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        "p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]",
        className
      )}
      {...props}
    />
  )
}

function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("text-muted-foreground mt-4 text-sm", className)}
      {...props}
    />
  )
}

export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
}
